<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><title>{{ $purchaseOrder->purchase_order_number ?? 'Purchase Order Draft' }}</title><style>body{font-family:Arial,sans-serif;color:#0f172a;margin:32px}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border:1px solid #cbd5e1;padding:8px;text-align:left}.num{text-align:right}.meta{display:grid;grid-template-columns:1fr 1fr;gap:12px}</style></head><body><h1>PURCHASE ORDER</h1><div class="meta"><p><strong>Number:</strong> {{ $purchaseOrder->purchase_order_number ?? 'DRAFT' }}</p><p><strong>Date:</strong> {{ $purchaseOrder->order_date->format('M d, Y') }}</p><p><strong>Supplier:</strong> {{ $purchaseOrder->supplier_name }}</p><p><strong>Delivery:</strong> {{ $purchaseOrder->delivery_location }}</p></div><table><thead><tr><th>Description</th><th>UOM</th><th class="num">Quantity</th><th class="num">Unit cost</th><th class="num">Net</th></tr></thead><tbody>@foreach($purchaseOrder->lines as $line)<tr><td>{{ $line->description }}</td><td>{{ $line->uom_code }}</td><td class="num">{{ $line->ordered_quantity }}</td><td class="num">{{ $line->unit_cost }}</td><td class="num">{{ $line->net_amount }}</td></tr>@endforeach</tbody></table><p class="num"><strong>Grand total: ₱{{ number_format((float)$purchaseOrder->grand_total, 2) }}</strong></p></body></html>
